package app.nemmail.api.mail;

import app.nemmail.api.common.BaseEntity;
import jakarta.persistence.Convert;
import jakarta.persistence.Entity;
import jakarta.persistence.Table;
import java.time.Instant;
import java.util.UUID;
import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.type.SqlTypes;

/**
 * One message, shared by every user it reaches; each user's flags live in {@link MailboxEntry}. The
 * full-text {@code search} column is generated by Postgres and not mapped.
 */
@Entity
@Table(name = "messages")
public class Message extends BaseEntity {

  private UUID threadId;
  private UUID fromUserId;
  private String fromEmail;
  private String fromName;
  private String subject;
  private String bodyHtml;
  private String bodyText;
  private String snippet;
  private Instant sentAt;
  private Instant sendAt;

  @Convert(converter = MessageStatus.Converter.class)
  private MessageStatus status;

  private UUID inReplyTo;

  /** AIInsights JSON from @nem/shared. */
  @JdbcTypeCode(SqlTypes.JSON)
  private String ai;

  protected Message() {}

  public Message(
      UUID id,
      UUID threadId,
      String fromEmail,
      String fromName,
      String subject,
      String bodyText,
      String snippet,
      Instant sentAt,
      MessageStatus status) {
    super(id);
    this.threadId = threadId;
    this.fromEmail = fromEmail;
    this.fromName = fromName;
    this.subject = subject;
    this.bodyText = bodyText;
    this.snippet = snippet;
    this.sentAt = sentAt;
    this.status = status;
  }

  public UUID getThreadId() {
    return threadId;
  }

  public UUID getFromUserId() {
    return fromUserId;
  }

  public void setFromUserId(UUID fromUserId) {
    this.fromUserId = fromUserId;
  }

  public String getFromEmail() {
    return fromEmail;
  }

  public String getFromName() {
    return fromName;
  }

  public String getSubject() {
    return subject;
  }

  public String getBodyHtml() {
    return bodyHtml;
  }

  public void setBodyHtml(String bodyHtml) {
    this.bodyHtml = bodyHtml;
  }

  public String getBodyText() {
    return bodyText;
  }

  public String getSnippet() {
    return snippet;
  }

  public Instant getSentAt() {
    return sentAt;
  }

  public Instant getSendAt() {
    return sendAt;
  }

  public void setSendAt(Instant sendAt) {
    this.sendAt = sendAt;
  }

  public MessageStatus getStatus() {
    return status;
  }

  public void setStatus(MessageStatus status) {
    this.status = status;
  }

  public UUID getInReplyTo() {
    return inReplyTo;
  }

  public void setInReplyTo(UUID inReplyTo) {
    this.inReplyTo = inReplyTo;
  }

  public String getAi() {
    return ai;
  }

  public void setAi(String ai) {
    this.ai = ai;
  }
}
